  /// One fan-out leg: [changed] becomes one `state.sync` event per entry
  /// on [target] (see [stateSyncEvent] for the protocol shape).
  void _sendStateSync(
    JsAppEngine target,
    Map<String, dynamic> changed, {
    required String writer,
