    urls[pair.key] = uri;
  }
  final icon = entry.iconFile;
  if (icon != null) {
    if (unsafe(id)) {
      throw CatalogError('bad widget id "$id"');
    }
    if (unsafe(icon)) {
      throw CatalogError('$id: unsafe icon name "$icon"');
    }
    urls[icon] = catalogAssetUri(_rawBaseUrl, 'widgets/$id/$icon');
