import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage();
const logs = [];
page.on('console', (m) => { if (m.text().includes('[probe]')) logs.push(m.text()); });
page.on('pageerror', (e) => logs.push('pageerror: ' + e.message));
// Phase 1: save, then RELOAD the page for real.
await page.goto('http://127.0.0.1:8791/?phase=save', { waitUntil: 'load' });
await page.waitForTimeout(2500);
const before = logs.join('|');
if (!before.includes('SAVED')) { console.log('PROBE FAIL: no SAVED —', before); process.exit(1); }
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2500);
// Phase 2 (fresh document, ?phase=load): read back through the helper.
const after = logs.join('|');
console.log(after);
const ok = after.includes('RELOAD OK') && !after.includes('FAILED') && !after.includes('pageerror');
console.log(ok ? 'RELOAD PROBE PASS' : 'RELOAD PROBE FAIL');
process.exit(ok ? 0 : 1);
